import { PlaceOrderCommand } from '../../application/dto/OrderDto';

/** A request whose shape is malformed before it reaches the application. */
export class BadRequestError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'BadRequestError';
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function requireString(value: unknown, field: string): string {
  if (typeof value !== 'string') {
    throw new BadRequestError(`'${field}' must be a string`);
  }
  return value;
}

/** Checks only the JSON shape; business validation (e.g. positive quantities) stays in the domain. */
export function parsePlaceOrderBody(body: unknown): PlaceOrderCommand {
  if (!isRecord(body)) {
    throw new BadRequestError('Request body must be a JSON object');
  }
  if (!Array.isArray(body.lines)) {
    throw new BadRequestError("'lines' must be an array");
  }
  const lines = body.lines.map((line: unknown, index: number) => {
    if (!isRecord(line) || typeof line.quantity !== 'number') {
      throw new BadRequestError(`'lines[${index}]' must have a string 'productId' and a numeric 'quantity'`);
    }
    return { productId: requireString(line.productId, `lines[${index}].productId`), quantity: line.quantity };
  });
  return { customerId: requireString(body.customerId, 'customerId'), lines };
}

export function parseStatusBody(body: unknown): string {
  if (!isRecord(body)) {
    throw new BadRequestError('Request body must be a JSON object');
  }
  return requireString(body.status, 'status');
}

